js面试原理笔记function sum(a, b, c, d, e) &#123; return a + b + c + d + e&#125;// 改写函数sum实现:参数传递到5个即可实现累加// sum(1)(2)(3)(4)(5)// sum(1)(2,3)(4)(5)// sum(1)(2,3,4)(5)// sum(1)(2,3)(4,5)
核心步骤: let nums = []function currySum(...args) &#123; nums.push(...args) if (nums.length &gt;= 5) &#123; const result=nums.slice(0,length).reduce((prev, curv) =&gt; prev + curv, 0) nums=[]//注意这里要清空,保证下次累加值正确 return result &#125; else &#123; return currySum &#125;&#125;
更通用的方法：支持参数个数可以自定义 function sumMaker(length)&#123; let nums = [] function currySum(...args) &#123; nums.push(...args) if (nums.length &gt;= length) &#123; const result=nums.slice(0,length).reduce((prev, curv) =&gt; prev + curv, 0) nums=[]//注意这里要清空,保证下次累加值正确 return result &#125; else &#123; return currySum &#125; &#125; return currySum;&#125;const sum4=sumMaker(4)console.log(sum4(1,2,3)(4))
类型判断 const typeOfTest = (type) =&gt; &#123; return (thing) =&gt; &#123; return typeof thing === type &#125;&#125;例子：const isString = typeOfTest(&#x27;string&#x27;);console.log(isString(&#x27;hello&#x27;)); // trueconsole.log(isString(123)); // false
函数柯里化应用举例：axios axios里请求不是每个都覆盖掉了，然后没有设置的config就用默认值替代
1.npx和npm区别：npx是临时安装用完命令后卸载，npm是安装。 2.热更新：更新代码，页面自动刷新 3.错误覆盖：代码错误在浏览器上直接显示 vite内置功能： 4.webpack：把文件打包,长千个js&#x2F;css合并成一个文件，减少请求次数 5.vite：启动更快，但是生态还不是特别完善，主要是webpack支持一些复杂的自定义配置，多页应用(每个页面都是独立的HTML)，每个页面都有自己独特的优化需求，比如说后台有大量js，但是用户访问频率低，自定义代码分割：有些页面不需要首屏加载，需要按需加载。还有特殊格式（md，proto）的处理，需要转换成json等。 6.ESLint + Prettier：代码规范检查，强制统一风格 7.Jset+React Testing Library:测试框架 8.环境变量：REACT_APP_开头，本质就是自定义变量的字符串 9.跨域：如果两个 URL 的协议、域名、端口有任何一个不同，它们就是 “不同源”，浏览器会阻止页面直接访问不同源的资源。这导致前端无法用本地的后端接口。解决方法：proxy配置，比如在package.json里， // package.json 中添加&#123; &quot;proxy&quot;: &quot;http://localhost:5000&quot;（后端接口网址）&#125;
就可以实现跨域 10.Create React App(CRA) eject是一个命令，作用是释放和暴露webpack和babel脚本等等配置文件，此时不可逆，可以自定义配置，但是失去cra项目自动更新的东西。可以使用craco覆盖部分配置,创建 craco.config.js： module.exports = &#123; webpack: &#123; configure: (webpackConfig) =&gt; &#123; // 添加自定义配置 return webpackConfig; &#125;, &#125;,&#125;;
11.传统 React 应用会把所有 JS 代码打包到一个文件中（如 main.js），导致：
首屏加载慢：用户必须等待整个文件下载完成才能看到页面 浪费流量：即使用户只访问部分功能，也需要加载全部代码
解决方案：动态导入（Dynamic Import）React 提供了 React.lazy 和 React.Suspense 来实现组件的懒加载： // 1. 使用 React.lazy 包裹动态导入const LazyComponent = React.lazy(() =&gt; import(&#x27;./LazyComponent&#x27;));function App() &#123; return ( // 2. 使用 Suspense 组件提供加载状态 &lt;React.Suspense fallback=&#123;&lt;div&gt;Loading...&lt;/div&gt;&#125;&gt; &lt;LazyComponent /&gt; &lt;/React.Suspense&gt; );&#125;
效果 按需加载：只有用户访问到 LazyComponent 时，才会加载对应的 JS 代码 并行优化：Webpack 会自动把懒加载的组件拆分成独立的 chunk（如 1.chunk.js） 更好的用户体验：加载过程中显示 fallback 内容（如加载中提示）
12.npm run build会进行优化： 添加哈希值：每次build更新哈希值，哈希值由内容决定，内容改变网页就要重新加载 代码压缩 图片css的压缩 未使用代码移除

背包问题总论01背包1.01背包二维数组版01背包，一个选一次#include &lt;iostream&gt;#include &lt;cstring&gt;#include &lt;algorithm&gt;using namespace std;const int N = 110;int v[N],w[N];int dp[N][1010];int main()&#123;int n,m;cin&gt;&gt;m&gt;&gt;n;for (int i = 1; i &lt;= n; i ++ ) cin&gt;&gt;v[i]&gt;&gt;w[i];for (int i = 1; i &lt;= n; i ++ )for (int j = 0; j &lt;= m; j ++ )&#123;dp[i][j]=dp[i-1][j];//如果j《v【i】if(j&gt;=v[i]) dp[i][j]=max(dp[i-1][j],dp[i-1][j-v[i]]+w[i]);//不选，和选了，加这个条件是因为如果不加，那会w［i］比0大的这种情况，会导致错误&#125;cout&lt;&lt;dp[n][m]&lt;&lt;endl;     return 0;&#125;

2.01背包优化版（模板）核心思路：
优点：空间复杂度低
1.公式优化
dp[i][j]=max(dp[i-1][j],dp[i-1][j-v[i]]+w[i]);也就是说dp[i-1][j]可以变成dp[j],dp[i-1][j-v[i]]可以变成dp[j-v[i]]

2.注意从后往前，因为最前面的
dp[i-1][j-v[i]]还要用#include &lt;iostream&gt;using namespace std;const int N=1010;int dp[N];int v[N],w[N];int main()&#123;    int n,m;    cin&gt;&gt;n&gt;&gt;m;    for(int i=1;i&lt;=n;i++) cin&gt;&gt;v[i]&gt;&gt;w[i];    for(int i=1;i&lt;=n;i++)    &#123;        for(int j=m;j&gt;=v[i];j--)        &#123;            dp[j]=max(dp[j],dp[j-v[i]]+w[i]);        &#125;    &#125;    cout&lt;&lt;dp[m];    return 0;&#125;

完全背包问题1.暴力版#include &lt;iostream&gt;#include &lt;cstring&gt;#include &lt;algorithm&gt;using namespace std;const int N = 1010;int dp[N][N];int v[N],w[N];int main()&#123;int n,V;cin&gt;&gt;n&gt;&gt;V;for (int i = 1; i &lt;= n; i ++ ) cin&gt;&gt;v[i]&gt;&gt;w[i];for (int i = 1; i &lt;= n; i ++ )for (int j = 0; j &lt;= V; j ++ )&#123;for (int k = 0; k&lt;= j/v[i]; k ++ )dp[i][j]=max(dp[i][j],dp[i-1][j-k*v[i]]+k*w[i]);//这里要dp[i-1][j-k*v[i]]+k*w[i]而不是dp[i][j-kv[i]]+k*w[i]：第i个物品选择k个，其余的都交给dp【i-1】，这个最大值&#125;cout&lt;&lt;dp[n][V]&lt;&lt;endl;return 0;&#125;

2.优化版（n平方）经过复杂数学推导得到的结论
![e9b09857046308979d0e77bf63a9b57](C:\Users\56419\Documents\WeChat Files\wxid_cwcjwwyfwb1322\FileStorage\Temp\e9b09857046308979d0e77bf63a9b57.jpg)
#include &lt;iostream&gt;using namespace std;int n,m;const int N=1010;int dp[N][N];int v[N],w[N];int main()&#123;    cin&gt;&gt;n&gt;&gt;m;    for(int i=1;i&lt;=n;i++) cin&gt;&gt;v[i]&gt;&gt;w[i];    for(int i=1;i&lt;=n;i++)    for(int j=1;j&lt;=m;j++)     &#123;        dp[i][j]=dp[i-1][j];        if(j&gt;=v[i]) dp[i][j]=max(dp[i-1][j],dp[i][j-v[i]]+w[i]);            &#125;    cout&lt;&lt;dp[n][m]&lt;&lt;endl;    return 0;&#125;

3.滚动数组优化（背）01背包滚动数组优化倒置，01从后往前遍历，完全从前往后遍历
#include &lt;iostream&gt;using namespace std;int n,m;const int N=1010;int dp[N];int v[N],w[N];int main()&#123;    cin&gt;&gt;n&gt;&gt;m;    for(int i=1;i&lt;=n;i++) cin&gt;&gt;v[i]&gt;&gt;w[i];    for(int i=1;i&lt;=n;i++)    for(int j=v[i];j&lt;=m;j++) dp[j]=max(dp[j],dp[j-v[i]]+w[i]);    cout&lt;&lt;dp[m]&lt;&lt;endl;    return 0;&#125;

多重背包问题1.暴力解完全背包问题加个数量限制就ok了
#include &lt;iostream&gt;using namespace std;int n,m;const int N=110;int dp[N][N];int v[N],w[N],s[N];int main()&#123;    cin&gt;&gt;n&gt;&gt;m;    for(int i=1;i&lt;=n;i++) cin&gt;&gt;v[i]&gt;&gt;w[i]&gt;&gt;s[i];        for(int i=1;i&lt;=n;i++)    for(int j=1;j&lt;=m;j++)    &#123;    dp[i][j]=dp[i-1][j];//初始化    for(int k=1;(k&lt;=j/v[i])&amp;&amp;(k&lt;=s[i]);k++) //从1开始遍历    if(v[i]&lt;=j) dp[i][j]=max(dp[i][j],dp[i-1][j-k*v[i]]+k*w[i]);//如果可以放    &#125;    cout&lt;&lt;dp[n][m]&lt;&lt;endl;    return 0;&#125;

–我是懒狗，以后再更新–
